// CSD_RATIONALE_BEGIN
// Building on attempt 2 (40.8%, the best), which used SafeRepetitionPenaltyStep(4.0)
// inside spans and CloseSpanWithinBudget when budget ≤ 80. Two targeted additions:
//
// 1. Loop/dead-end escape:
//    The 7 malformed cases show `!`-repetition loops (e.g., `!!!!!!!!!`) and
//    comparison-operator dead-ends (e.g., `==!`). Detect them by:
//    (a) DeadEndDetection(threshold=2): fewer than 2 valid next tokens → extreme dead-end
//    (b) triple-repeat check: last 3 tokens in currentConstrainedOut are identical
//    On detection: RollbackConstrainedSuffix to restore a valid prefix, then
//    CloseSpanWithinBudget(remaining) to close with all remaining budget and break.
//    This does NOT increment steps before calling CloseSpanWithinBudget; we set
//    steps := maxSteps to account for the full budget consumed.
//
// 2. Improved guidance:
//    Added explicit prohibition of `^` (use `**` instead), comparison operators
//    (==, !=, <, >, <=, >=), and a note to use parentheses for precedence clarity.
//    Attempt 12 removed `**` which broke exponential cases; it's restored here.
//
// Core structure unchanged from attempt 2:
//   Phase 1: free UnconstrainedStep outside spans until RenderedEndsWith "<<"
//   Phase 2: SafeRepetitionPenaltyStep(4.0) inside spans with immediate close
//             when IsCompletePrefix
//   Budget guard: when remaining ≤ 80 inside span → CloseSpanWithinBudget
//   Final cleanup: CloseSpanWithinBudget on any open span after loop
//
// The per-span step limit from attempt 12 (which caused regression) is NOT included.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (remaining <= closeReserve branch):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut).
//     Both closed (ci=false, vacuous) and still-open paths preserved. ✓
//
//   (outside span branch):
//     RenderedEndsWith "<<" sets currentConstrainedOut := [] which satisfies
//     IsValidPrefix([]) by method precondition. Otherwise insideConstrainedOut
//     stays false (vacuous). ✓
//
//   (IsCompletePrefix branch):
//     CloseConstrainedSpan sets insideConstrainedOut := false; implication vacuous. ✓
//
//   (loopDetected branch):
//     RollbackConstrainedSuffix postcondition: rc is parser-valid.
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (normal constrained step branch):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS; on non-EOS,
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (final cleanup):
//     Same argument as closeReserve branch. ✓
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (remaining <= closeReserve, s = steps_before, remaining = maxSteps - s):
//     CloseSpanWithinBudget(remaining): |cg| <= |generated| + remaining
//     <= |generatedPrefix| + s + maxSteps - s = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside span): steps += 1; at most one token appended to generated. ✓
//
//   (IsCompletePrefix): steps += 1; CloseConstrainedSpan appends at most one `>>`. ✓
//
//   (loopDetected, s = steps_before):
//     After rollback: |rg| <= |generated| (rollback shortens or preserves length).
//     CloseSpanWithinBudget(remaining): |cg| <= |rg| + remaining
//     <= |generated| + remaining <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (normal constrained step): steps += 1; AppendConstrainedToken appends exactly 1 token
//     (non-EOS path) or 0 tokens (EOS path with break). ✓
//
//   (final cleanup): Same as closeReserve branch. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use only: numbers, problem variables, +, -, *, **, /, //, %, (), int(). " +
  "Use ** for exponentiation, not ^. " +
  "Use // for floor (integer) division. " +
  "Use parentheses to make operator precedence explicit. " +
  "Use int() when an integer result is needed. " +
  "Use the exact variable names given in the problem. Do not substitute numeric values for variables. " +
  "Do NOT use comparison operators (==, !=, <, >, <=, >=) inside << >>. " +
  "Do NOT write assignments (no = outside of ** inside << >>).");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close using dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Detect repetition loop or dead-end before constrained step
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    var n := |currentConstrainedOut|;
    var tripleRepeat := n >= 3 &&
      currentConstrainedOut[n-1] == currentConstrainedOut[n-2] &&
      currentConstrainedOut[n-2] == currentConstrainedOut[n-3];

    if narrow || tripleRepeat {
      // Rollback to last parser-valid prefix and force-close with remaining budget
      var rg, rc := helpers.RollbackConstrainedSuffix(parser, generated, currentConstrainedOut);
      generated := rg;
      currentConstrainedOut := rc;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
      break;
    } else {
      // Constrained generation with repetition penalty to break !-loop dead ends
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

